<svg width="778" height="755" viewBox="0 0 778 755" fill="none" xmlns="http://www.w3.org/2000/svg" class="size-full"><style>
@keyframes dashAnimation {
  to {
    stroke-dashoffset: -16; 
  }
}
.animated-border  {
  animation: dashAnimation .7s linear infinite;
}



@keyframes pulse {
  0%, 100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.08);
  }
}

.pulse {
  animation: pulse 2s ease-in-out infinite;
  transform-origin: center;
  transform-box: fill-box;
}


@keyframes pulse-out {
  0%, 100% {
    transform: scale(1);
  }
  50% {
    transform: scale(1.08);
  }
}

.pulse-out {
  animation: pulse-out 2s ease-in-out infinite;
  transform-origin: center;
  transform-box: fill-box;
}

/* This one starts halfway through the animation cycle */
.pulse-delayed {
  animation: pulse-out 3.5s ease-in-out infinite;
  animation-delay: 1.75s;
  transform-origin: center;
  transform-box: fill-box;
}



@keyframes pulse-large {
    0%, 100% {
      transform: scale(1);
    }
    50% {
      transform: scale(1.3);
    }
  }
  
  .pulse-large {
    animation: pulse-large 3s ease-in-out infinite;
    transform-origin: center;
    transform-box: fill-box;
  }
@keyframes rotate {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}

.rotate {
  animation: rotate 4s linear infinite;
  transform-origin: center;
  transform-box: fill-box; /* Important for SVG paths */
}


